// Output: what a compile is written as, file name -> content (Write); the
// caller writes them (the CLI to a directory, a server to git).

package compiler

import (
	"bytes"

	"go.yaml.in/yaml/v3"
)

// generated: the first line of the umbrella's values, Go's mark of a
// generated file, which GitHub, linters and editors know.
const generated = "# Code generated by okdp-compile. DO NOT EDIT.\n"

// Output: the files Write gives for a compile, as the flags of
// okdp-compile choose them.
type Output struct {
	Dependencies bool // --mkdag: DependenciesFile
}

// Write: what `okdp-compile -o <dir>` writes for res, file name -> content,
// with the files o asks for:
//
//   - the instance as one chart (umbrella): Chart.yaml, named and versioned
//     after service.yaml (Result.Service, Result.Version), an umbrella over
//     the upstream charts of its keys (Result.Charts, aliased to the key
//     when it is not the chart's name), and UmbrellaValues, the final
//     values of each key under the key;
//   - with Dependencies (--mkdag), DependenciesFile.
//
// The YAML files are indented by 2 spaces. Every file is built before
// Write returns: one that fails leaves the caller nothing to write. res is
// what Compile returned: Write does not check it again.
func Write(res *Result, o Output) (map[string][]byte, error) {
	files, err := umbrella(res)
	if err != nil {
		return nil, err
	}
	if o.Dependencies {
		if files[DependenciesFile], err = marshal(res.Dependencies); err != nil {
			return nil, err
		}
	}
	return files, nil
}

// DependenciesFile: Result.Dependencies as a YAML list, [] when there is
// none (Output.Dependencies): the instances the connection references
// point to, for a deployer that orders the releases (Flux dependsOn, Argo
// CD sync waves).
const DependenciesFile = "okdp.dependencies.yaml"

// IsOutputFile: name is a file Write gives, with any Output:
// umbrellaChartFile and UmbrellaValues (umbrella), DependenciesFile. A caller that keeps the files of an instance in a
// directory may remove those a compile no longer gives, and no other.
func IsOutputFile(name string) bool {
	switch name {
	case umbrellaChartFile, UmbrellaValues, DependenciesFile:
		return true
	}
	return false
}

// valuesFile: v as a values file, its first line generated (marshal).
func valuesFile(v any) ([]byte, error) {
	b, err := marshal(v)
	if err != nil {
		return nil, err
	}
	return append([]byte(generated), b...), nil
}

// marshal: v as a YAML document indented by 2 spaces.
func marshal(v any) ([]byte, error) {
	var buf bytes.Buffer
	enc := yaml.NewEncoder(&buf)
	enc.SetIndent(2)
	if err := enc.Encode(v); err != nil {
		return nil, err
	}
	if err := enc.Close(); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}
